import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { writeFile, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { testServer } from '../../server/test/helpers.js';
const execute = promisify(execFile);
let server, owner, org, config;
beforeEach(async () => {
  server = await testServer(); owner = server.agent();
  const signup = await owner('POST', '/auth/signup', { name: 'CLI', email: 'cli@project.test', password: 'correct-horse-123' });
  org = (await owner('POST', '/orgs', { name: 'CLI Planning' })).data.organization;
  config = path.join(server.ctx.config.dataDir, 'cli.json');
  await writeFile(config, JSON.stringify({ url: server.url, cookie: signup.cookie }), { mode: 0o600 });
});
afterEach(async () => { await server.close(); });
async function cli(args) {
  const result = await execute(process.execPath, [fileURLToPath(new URL('../bin/crew.js', import.meta.url)), ...args, '--config', config, '--json'], { timeout: 15000 });
  return JSON.parse(result.stdout);
}
test('actual CLI creates updates and reads a project over HTTP', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'CL', '--name', 'CLI Project']);
  assert.equal(project.key, 'CL');
  await cli(['project', 'update', project.id, '--name', 'Renamed', '--description', 'CLI description']);
  assert.equal((await cli(['project', 'show', project.id])).project.description, 'CLI description');
  assert.equal((await cli(['project', 'list', '--org', org.id])).items[0].name, 'Renamed');
});
test('actual CLI archives restores and requires deliberate project deletion', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'AR', '--name', 'Archive']);
  assert.equal((await cli(['project', 'archive', project.id])).project.archived, true);
  assert.equal((await cli(['project', 'restore', project.id])).project.archived, false);
  await assert.rejects(() => cli(['project', 'delete', project.id]), /requires --yes/);
  assert.equal((await cli(['project', 'delete', project.id, '--yes'])).ok, true);
});
test('actual CLI board moves persist ordered status changes', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'BD', '--name', 'Board']);
  const issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'CLI board' })).data.issue;
  const moved = await cli(['board', 'move', issue.id, '--status', project.statuses[1].id]);
  assert.equal(moved.issue.statusId, project.statuses[1].id);
  assert.equal((await cli(['board', 'show', project.id])).columns[1].issues[0].id, issue.id);
});
test('actual CLI board bulk changes labels and assignment through the API', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'BK', '--name', 'Bulk']);
  const issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'CLI bulk' })).data.issue;
  const label = (await owner('POST', '/projects/' + project.id + '/labels', { name: 'Ship' })).data.label;
  const result = await cli(['board', 'bulk', project.id, '--issues', issue.id, '--status', project.statuses[2].id, '--add-labels', label.id, '--assignee', 'none']);
  assert.equal(result.count, 1); assert.equal(result.items[0].labels[0].id, label.id); assert.equal(result.items[0].assigneeId, null);
});
test('actual CLI sprint lifecycle scopes and carries unfinished issues', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'SR', '--name', 'Sprint CLI']);
  const issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Carry me', estimate: 8 })).data.issue;
  const first = (await cli(['sprint', 'create', '--project', project.id, '--name', 'First', '--start', '2026-10-01', '--end', '2026-10-07'])).sprint;
  const next = (await cli(['sprint', 'create', '--project', project.id, '--name', 'Next', '--start', '2026-10-08', '--end', '2026-10-14'])).sprint;
  await cli(['sprint', 'add', first.id, '--issues', issue.id]); await cli(['sprint', 'start', first.id]);
  const completed = await cli(['sprint', 'complete', first.id, '--carry-over', next.id]);
  assert.deepEqual(completed.result.carriedIssueIds, [issue.id]);
  assert.equal((await cli(['sprint', 'scope', next.id])).issues[0].issueId, issue.id);
  assert((await cli(['sprint', 'burndown', first.id])).days.length > 0);
});
test('actual CLI streams binary upload and verified download without replacing existing output', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'AT', '--name', 'Attachment CLI']);
  const issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'CLI attachment' })).data.issue;
  const source = path.join(server.ctx.config.dataDir, 'source.bin'), output = path.join(server.ctx.config.dataDir, 'download.bin');
  const bytes = Buffer.from([0, 255, 13, 10, 65, 90, 0]); await writeFile(source, bytes);
  const { attachment } = await cli(['board', 'attach', issue.id, '--file', source, '--name', 'CLI bytes.bin']);
  const downloaded = await cli(['board', 'download', attachment.id, '--output', output]);
  assert.equal(downloaded.sha256, attachment.sha256); assert.deepEqual(await readFile(output), bytes);
  await assert.rejects(() => cli(['board', 'download', attachment.id, '--output', output]), /EEXIST/);
  assert.deepEqual(await readFile(output), bytes);
  assert.equal((await cli(['board', 'attachments', issue.id])).items[0].id, attachment.id);
  assert.equal((await cli(['board', 'attachment-delete', attachment.id, '--yes'])).ok, true);
});
test('actual CLI upload hash mismatch reports failure and leaves no metadata', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'HM', '--name', 'Hash CLI']);
  const issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Hash mismatch' })).data.issue;
  const file = path.join(server.ctx.config.dataDir, 'mismatch.bin'); await writeFile(file, 'bytes');
  await assert.rejects(() => cli(['board', 'attach', issue.id, '--file', file, '--sha256', '0'.repeat(64)]), /SHA-256/);
  assert.equal((await cli(['board', 'attachments', issue.id])).items.length, 0);
});
test('actual CLI workflow command submits a file and persists status order', async () => {
  const { project } = await cli(['project', 'create', '--org', org.id, '--key', 'WF', '--name', 'Workflow']);
  const file = path.join(server.ctx.config.dataDir, 'workflow.json');
  await writeFile(file, JSON.stringify([{ name: 'Ready', category: 'todo' }, { name: 'Finished', category: 'done' }]));
  await cli(['project', 'workflow-set', project.id, '--file', file]);
  assert.deepEqual((await cli(['project', 'workflow', project.id])).statuses.map(row => row.name), ['Ready', 'Finished']);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { scopePreview, completionPreview, chartPoints, chartPath } from '../src/pages/work/sprint-state.js';
import { formatBytes, uploadProgress, validateUpload, uploadAttachment } from '../src/pages/work/attachment-state.js';
test('scope preview includes only selected issues and counts unestimated work', () => {
  assert.deepEqual(scopePreview([{ id: 'a', estimate: 3 }, { id: 'b', estimate: null }, { id: 'c', estimate: 8 }], new Set(['a', 'b'])), { issueIds: ['a', 'b'], count: 2, points: 3 });
});
test('completion preview separates completed and unfinished carry-over', () => {
  assert.deepEqual(completionPreview([{ issueId: 'a', done: true, estimate: 5, remaining: 0 }, { issueId: 'b', done: false, estimate: 8, remaining: 8 }]), { completedCount: 1, unfinishedCount: 1, completedPoints: 5, unfinishedPoints: 8, unfinishedIssueIds: ['b'] });
});
test('burndown chart omits future actuals and produces finite coordinates', () => {
  const points = chartPoints([{ date: '2026-10-01', scope: 5, remaining: 5, idealRemaining: 5 }, { date: '2026-10-02', scope: 5, remaining: null, idealRemaining: 0 }], 'remaining');
  assert.equal(points.length, 1); assert(Number.isFinite(points[0].x)); assert(chartPath(points).startsWith('M'));
});
test('upload validation reports file and configured size errors', () => {
  assert(validateUpload(null, 100)); assert(validateUpload({ name: 'large.bin', size: 101 }, 100));
  assert.equal(validateUpload({ name: 'zero.bin', size: 0 }, 100), null); assert(validateUpload({ name: '../x', size: 1 }, 100));
  assert.equal(formatBytes(1024), '1.0 KiB'); assert.equal(uploadProgress(500, 100), 100); assert.equal(uploadProgress(0, 0), 0);
});
function requestFactory({ status = 201, response = { attachment: { id: 'a' } } } = {}) {
  const calls = {};
  const xhr = { status, responseText: JSON.stringify(response), upload: {},
    open(method, url) { calls.method = method; calls.url = url; },
    setRequestHeader(name, value) { (calls.headers ??= {})[name] = value; },
    send(file) { calls.file = file; this.upload.onprogress({ loaded: 4, total: 4, lengthComputable: true }); queueMicrotask(() => this.onload()); },
    abort() { this.onabort(); }
  };
  return { calls, xhr, createRequest: () => xhr };
}
test('upload transport sends raw file with CSRF and reports progress/result', async () => {
  const factory = requestFactory(), progress = [], file = { name: 'a b.bin', size: 4 };
  const result = await uploadAttachment({ issueId: 'issue', file, onProgress: value => progress.push(value), createRequest: factory.createRequest });
  assert.equal(result.attachment.id, 'a'); assert.equal(factory.calls.file, file); assert.equal(factory.calls.headers['X-Crew-Request'], '1');
  assert(factory.calls.url.includes('a%20b.bin')); assert.deepEqual(progress, [{ loaded: 4, total: 4 }]);
});
test('upload transport preserves stable server errors and supports pre-cancellation', async () => {
  const factory = requestFactory({ status: 413, response: { error: { code: 'TOO_LARGE', message: 'Too big', details: { maxBytes: 4 } } } });
  await assert.rejects(() => uploadAttachment({ issueId: 'a', file: { name: 'a', size: 8 }, createRequest: factory.createRequest }), { code: 'TOO_LARGE', status: 413 });
  const controller = new AbortController(); controller.abort();
  await assert.rejects(() => uploadAttachment({ issueId: 'a', file: { name: 'a', size: 0 }, signal: controller.signal, createRequest: requestFactory().createRequest }), /cancelled/);
});
